/// Merge two key/value tables.
fn merge_tables(mut base: Table, replacement: Table) -> Table {
    for (key, value) in replacement {
        let value = match base.remove(&key) {
            Some(base_value) => merge(base_value, value),
            None => value,
        };
        base.insert(key, value);
    }

    base
}

